namespace RonSijm.FluidHumidifier.Factories.MSK;

public class ChannelFactory(string resourceName = null, Action<Humidifier.MSK.Channel> factoryAction = null) : ResourceFactory<Humidifier.MSK.Channel>(resourceName)
{

    internal List<InnerChannelTopicConfigurationFactory> TopicConfigurationListFactories { get; set; } = [];

    internal InnerChannelEncryptionConfigurationFactory EncryptionConfigurationFactory { get; set; }

    internal InnerChannelIcebergDestinationConfigurationFactory IcebergDestinationConfigurationFactory { get; set; }

    internal InnerChannelS3DestinationConfigurationFactory S3DestinationConfigurationFactory { get; set; }

    internal InnerChannelChannelLoggingInfoFactory LoggingInfoFactory { get; set; }

    protected override Humidifier.MSK.Channel Create()
    {
        var channelResult = CreateChannel();
        factoryAction?.Invoke(channelResult);

        return channelResult;
    }

    private Humidifier.MSK.Channel CreateChannel()
    {
        var channelResult = new Humidifier.MSK.Channel
        {
            GivenName = InputResourceName,
        };

        return channelResult;
    }
    public override void CreateChildren(Humidifier.MSK.Channel result)
    {
        base.CreateChildren(result);

        result.TopicConfigurationList = TopicConfigurationListFactories.Any() ? TopicConfigurationListFactories.Select(x => x.Build()).ToList() : null;
        result.EncryptionConfiguration ??= EncryptionConfigurationFactory?.Build();
        result.IcebergDestinationConfiguration ??= IcebergDestinationConfigurationFactory?.Build();
        result.S3DestinationConfiguration ??= S3DestinationConfigurationFactory?.Build();
        result.LoggingInfo ??= LoggingInfoFactory?.Build();
    }

} // End Of Class

